"use client";
import {useEffect,useState} from "react";import {api} from "@/lib/api-client";import {formatNaira} from "@/lib/mock-data";
type Overview={storeViews:number;productViews:number;whatsappClicks:number;externalClicks:number;orders:number;revenue:number;grossSales:number;conversionRate:number};type BestProduct={productId:string;productName:string;unitsSold:number;revenue:number};type TrafficSource={source:string;count:number};type PromotionEvent={promotionType:string;event:string;count:number;revenue:number};
export default function VendorAnalyticsPage(){const[o,setO]=useState<Overview|null>(null);const[p,setP]=useState<BestProduct[]|null>(null);const[s,setS]=useState<TrafficSource[]|null>(null);const[pe,setPe]=useState<PromotionEvent[]|null>(null);const[error,setError]=useState<string|null>(null);useEffect(()=>{api.get<{overview:Overview}>("/api/analytics/vendor/overview").then(r=>setO(r.overview)).catch(e=>setError(e instanceof Error?e.message:"Unable to load overview analytics."));api.get<{products:BestProduct[]}>("/api/analytics/vendor/best-products").then(r=>setP(r.products)).catch(e=>setError(e instanceof Error?e.message:"Unable to load product analytics."));api.get<{sources:TrafficSource[]}>("/api/analytics/vendor/traffic-sources").then(r=>setS(r.sources)).catch(e=>setError(e instanceof Error?e.message:"Unable to load traffic analytics."));api.get<{events:PromotionEvent[]}>("/api/analytics/promotions/mine").then(r=>setPe(r.events)).catch(()=>setPe([]));},[]);return <div className="shell py-8"><h1 className="text-xl font-bold text-graphite-900">Analytics</h1>{error&&<p role="status" className="mt-3 rounded-xl border border-ember-200 bg-ember-50 p-3 text-sm text-ember-800">{error}</p>}{o&&<div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4">{[["Store views",o.storeViews.toLocaleString()],["Product views",o.productViews.toLocaleString()],["WhatsApp clicks",o.whatsappClicks.toLocaleString()],["External clicks",o.externalClicks.toLocaleString()],["Orders",o.orders.toLocaleString()],["Revenue",formatNaira(o.revenue)],["Gross sales",formatNaira(o.grossSales)],["Conversion",`${o.conversionRate}%`]].map(([l,v])=><Stat key={l} label={l} value={v}/>)}</div>}<div className="mt-8 grid gap-6 lg:grid-cols-2"><Panel title="Best-performing products">{p===null?<p>Loading…</p>:p.length===0?<p>No sales yet.</p>:p.map(x=><Row key={x.productId} left={x.productName} right={`${x.unitsSold} sold · ${formatNaira(x.revenue)}`}/>)}</Panel><Panel title="Traffic sources">{s===null?<p>Loading…</p>:s.length===0?<p>No referral clicks recorded yet.</p>:s.map(x=><Row key={x.source} left={x.source} right={String(x.count)}/>)}</Panel><Panel title="Promotion performance">{pe===null?<p>Loading…</p>:pe.length===0?<p>No promotion events yet.</p>:pe.map((x,i)=><Row key={`${x.promotionType}-${x.event}-${i}`} left={`${x.promotionType} · ${x.event}`} right={`${x.count} · ${formatNaira(x.revenue)}`}/>)}</Panel></div></div>}
function Panel({title,children}:{title:string;children:React.ReactNode}){return <div><h2 className="mb-3 text-sm font-bold uppercase tracking-wide text-graphite-600">{title}</h2><div className="flex flex-col gap-1.5 text-sm">{children}</div></div>}function Row({left,right}:{left:string;right:string}){return <div className="flex items-center justify-between rounded-card border border-graphite-200 px-3 py-2"><span className="truncate pr-2">{left}</span><span className="shrink-0 font-mono text-graphite-600">{right}</span></div>}function Stat({label,value}:{label:string;value:string}){return <div className="rounded-card border border-graphite-200 p-4"><p className="text-xs text-graphite-600">{label}</p><p className="mt-0.5 font-mono text-lg font-bold text-graphite-900">{value}</p></div>}
